//! Turns the SFCC API reference into the index `isml-lsp` embeds.
//!
//! The reference ships as one markdown file per class in the `sfcc-dev-mcp`
//! npm package. Reading it at run time would put a node_modules between the
//! editor and an answer, so it is compiled in instead — and regenerated by
//! hand when the platform gains a class:
//!
//! ```text
//! npm pack sfcc-dev-mcp && tar -xzf sfcc-dev-mcp-*.tgz
//! cargo run --bin generate-api -- package/dist/docs src/api.json
//! ```

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Long prose helps nobody in a completion popup and costs binary size.
const DESCRIPTION_LIMIT: usize = 220;

#[derive(Default, serde::Serialize)]
struct Class {
    #[serde(rename = "d", skip_serializing_if = "String::is_empty")]
    description: String,
    #[serde(rename = "c", skip_serializing_if = "Vec::is_empty")]
    constants: Vec<Member>,
    #[serde(rename = "p", skip_serializing_if = "Vec::is_empty")]
    properties: Vec<Member>,
    #[serde(rename = "m", skip_serializing_if = "Vec::is_empty")]
    methods: Vec<Member>,
}

#[derive(serde::Serialize)]
struct Member {
    #[serde(rename = "n")]
    name: String,
    /// A type for a property or constant, a signature for a method.
    #[serde(rename = "s", skip_serializing_if = "String::is_empty")]
    shape: String,
    #[serde(rename = "d", skip_serializing_if = "String::is_empty")]
    description: String,
}

fn main() {
    let mut args = std::env::args().skip(1);
    let (Some(docs), Some(out)) = (args.next(), args.next()) else {
        eprintln!("usage: generate-api <docs-dir> <out.json>");
        std::process::exit(2);
    };

    let mut classes: BTreeMap<String, Class> = BTreeMap::new();
    for file in markdown_files(Path::new(&docs)) {
        if let Some((name, class)) = read_class(&file) {
            classes.insert(name, class);
        }
    }

    let json = serde_json::to_string(&classes).expect("serialise");
    fs::write(&out, &json).expect("write");
    println!(
        "{} classes, {} KB -> {out}",
        classes.len(),
        json.len() / 1024
    );
}

fn markdown_files(root: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let Ok(entries) = fs::read_dir(root) else {
        return files;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            files.extend(markdown_files(&path));
        } else if path.extension().is_some_and(|extension| extension == "md") {
            files.push(path);
        }
    }
    files
}

/// `## Package: dw.system` plus `# Class Site` gives the qualified name; the
/// files that carry neither are guides, not classes.
fn read_class(file: &Path) -> Option<(String, Class)> {
    let text = fs::read_to_string(file).ok()?;
    let package = after(&text, "## Package: ")?;
    let name = after(&text, "# Class ").or_else(|| after(&text, "# Interface "))?;

    let mut class = Class {
        description: section(&text, "## Description")
            .map(|body| summarise(&body))
            .unwrap_or_default(),
        ..Default::default()
    };

    for (heading, into) in [
        ("## Constants", &mut class.constants),
        ("## Properties", &mut class.properties),
    ] {
        if let Some(body) = section(&text, heading) {
            *into = typed_members(&body);
        }
    }
    if let Some(body) = section(&text, "## Method Details") {
        class.methods = signed_members(&body);
    }
    // A class with only a summary section still deserves its method names.
    if class.methods.is_empty() {
        if let Some(body) = section(&text, "## Method Summary") {
            class.methods = signed_members(&body);
        }
    }

    Some((format!("{package}.{name}"), class))
}

/// The text of a `### Name` block: `**Type:** X` or `**Signature:** X`, then
/// the description.
fn typed_members(body: &str) -> Vec<Member> {
    entries(body)
        .into_iter()
        .map(|(name, block)| Member {
            name,
            shape: field(&block, "**Type:**").unwrap_or_default(),
            description: summarise(&strip_fields(&block)),
        })
        .collect()
}

fn signed_members(body: &str) -> Vec<Member> {
    entries(body)
        .into_iter()
        .map(|(name, block)| Member {
            name,
            shape: field(&block, "**Signature:**")
                .map(|text| text.trim_matches('`').to_string())
                .unwrap_or_default(),
            // A method block labels its prose, and is followed by the
            // parameter and return lists, which are not the description.
            description: summarise(&labelled(&block, "**Description:**")),
        })
        .collect()
}

/// The text of a `**Label:** …` entry, including the lines it wraps onto,
/// which run until the next label.
fn labelled(block: &str, label: &str) -> String {
    let mut collected: Vec<&str> = Vec::new();
    let mut inside = false;
    for line in block.lines() {
        let trimmed = line.trim();
        if let Some(head) = trimmed.strip_prefix(label) {
            inside = true;
            collected.push(head.trim());
            continue;
        }
        if inside && (trimmed.starts_with("**") || trimmed == "---") {
            break;
        }
        if inside {
            collected.push(trimmed);
        }
    }
    collected.join(" ")
}

fn entries(body: &str) -> Vec<(String, String)> {
    let mut found: Vec<(String, String)> = Vec::new();
    for chunk in body.split("\n### ").skip(1) {
        let (heading, rest) = chunk.split_once('\n').unwrap_or((chunk, ""));
        let name = heading.trim().to_string();
        if name.is_empty() || name.contains(' ') {
            continue;
        }
        // An overloaded method appears once per signature; the first wins.
        if found.iter().any(|(existing, _)| *existing == name) {
            continue;
        }
        found.push((name, rest.to_string()));
    }
    found
}

fn section(text: &str, heading: &str) -> Option<String> {
    let start = text.find(&format!("\n{heading}\n"))? + heading.len() + 2;
    let rest = &text[start..];
    let end = rest.find("\n## ").unwrap_or(rest.len());
    Some(rest[..end].to_string())
}

fn field(block: &str, label: &str) -> Option<String> {
    block
        .lines()
        .find_map(|line| line.trim().strip_prefix(label))
        .map(|value| value.trim().to_string())
}

/// Everything that is not a `**Label:**` line — what is left is the prose.
fn strip_fields(block: &str) -> String {
    block
        .lines()
        .filter(|line| !line.trim().starts_with("**") && line.trim() != "---")
        .collect::<Vec<_>>()
        .join(" ")
}

fn after(text: &str, marker: &str) -> Option<String> {
    let start = text.find(marker)? + marker.len();
    let line = text[start..].lines().next()?.trim();
    (!line.is_empty()).then(|| line.to_string())
}

fn summarise(text: &str) -> String {
    let flat = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let flat = flat.trim_start_matches("**Description:**").trim();
    if flat.len() <= DESCRIPTION_LIMIT {
        return flat.to_string();
    }
    let cut = flat[..DESCRIPTION_LIMIT]
        .rfind(' ')
        .unwrap_or(DESCRIPTION_LIMIT);
    format!("{}…", &flat[..cut])
}
